package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	r, c := int(num()), int(num())
	a := make([][]int64, r)
	for i := range a {
		a[i] = make([]int64, c)
		for j := range a[i] {
			a[i][j] = num()
		}
	}
	q := int(num())
	for ; q > 0; q-- {
		switch token() {
		case "swapRows":
			x, y := num(), num()
			a[x], a[y] = a[y], a[x]
		case "swapColumns":
			x, y := num(), num()
			for _, row := range a {
				row[x], row[y] = row[y], row[x]
			}
		case "reverseRow":
			slices.Reverse(a[num()])
		case "reverseColumn":
			x := num()
			for i := 0; i < len(a)/2; i++ {
				k := len(a) - 1 - i
				a[i][x], a[k][x] = a[k][x], a[i][x]
			}
		default:
			// Clockwise: new[i][j] = old[rows - 1 - j][i].
			rows, cols := len(a), 0
			if rows > 0 {
				cols = len(a[0])
			}
			b := make([][]int64, cols)
			for i := range b {
				b[i] = make([]int64, rows)
				for j := range b[i] {
					b[i][j] = a[rows-1-j][i]
				}
			}
			a = b
		}
	}
	out := []byte{}
	for i, row := range a {
		if i > 0 {
			out = append(out, '\n')
		}
		for j, v := range row {
			if j > 0 {
				out = append(out, ' ')
			}
			out = strconv.AppendInt(out, v, 10)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
